# -*- coding: utf-8 -*-
"""058 cabinet door for IngeTrazo. Original SKP geometry and panel options.
No SketchUp installation, Ruby runtime, network or OpenSKP dependency required.
"""
from __future__ import annotations
import ast
import base64
import copy
import json
import math
import operator
import re
import zlib

KEY = 'one_degree_cabinet_door'
VERSION = '1.25.1'
DOOR058_STYLES = ('door058_one','door058_two','door058_three','glassdoor')
FRAME058_STYLES = ('frame_double','frame_single')
REBATE_STYLES = ('rebate_double','rebate_single')
FRAME_STYLES = (*FRAME058_STYLES,*REBATE_STYLES,'plain_frame')
LENGTH_ONLY_STYLES = ('handle','lightstrip','hangingrail')
THRESHOLD_STYLES = ('threshold_door','threshold_shower')
MOLDING_STYLES = ('molding1216','molding058')
GRID_STYLES = ('grid','cabinet_grid')
GUIDE_NAME = '門縫定位線（每側0.2cm）'
# Geometry, formulas and defaults extracted directly from the supplied SKP.
_DATA = ''
STYLES = json.loads(zlib.decompress(base64.b64decode(_DATA)))
TEMPLATE = STYLES['one']
DEFAULTS = TEMPLATE['defaults']


def style_of(group=None):
    return group.ext[KEY].get('style_id','one') if group is not None else 'one'


def style_template(style_id='one'):
    if style_id not in STYLES: raise ValueError('不支援的門片樣式。')
    return STYLES[style_id]


def validate(params, style_id='one'):
    if style_id=='louverdoor':params=louver_params(params)
    defaults = style_template(style_id)['defaults']
    p = {k: float(params.get(k,defaults[k]) if k=='depth' or (style_id=='glassdoor' and k=='belly') or (style_id=='door058_two' and k=='mid') else params[k]) for k in defaults}
    if not all(math.isfinite(v) and (0<=v<3 if k=='recess' else 0<=v<=100 if k in ('opening','mid_position') else 0<v<=10000) for k,v in p.items()):
        raise ValueError('尺寸必須大於 0，且不超過 10000 公分。')
    if style_id=='louverdoor':
        p['show_mid']=bool(params.get('show_mid',True))
        if min(p['width']-2*p['side']-4,p['rail']-1,p['side']-1,p['mid']-1)<=.01:
            raise ValueError('左右框之間須保留大於 4.01 cm 的開口；上下框、左右框及中橫槓寬度須大於 1.01 cm，以保留圓角。')
        regions=louver_regions(p)
        if min(hi-lo for _,lo,hi in regions)<STYLES[style_id]['pitch_cm']:
            raise ValueError('每個百葉區至少須有 6.32 cm；請增加門高、減少框寬或調整中橫槓位置。')
        return p
    if style_id=='emptycabinet':
        b,bt=p['thickness'],p['back_thickness']
        if min(b,bt,p['width']-2*b,p['height']-2*b,p['depth']-bt)<=.01:
            raise ValueError('四周板厚、背板厚及櫃內淨寬、淨高、淨深都須大於 0.01 公分。')
        return p
    if style_id=='hangingrail':
        p['hide_guide']=bool(params.get('hide_guide',False))
        if p['width']<=5.01:raise ValueError('吊衣桿長度須大於 5.01 公分，才能保留兩端各 2.5 公分的端座。')
        return p
    if style_id=='shelves':
        p['hide_guide']=bool(params.get('hide_guide',False))
        if p['count']!=int(p['count']) or not 1<=p['count']<=100:
            raise ValueError('層板數量請輸入 1～100 的整數。')
        p['count']=int(p['count'])
        gap=(p['height']-p['count']*p['thickness'])/(p['count']+1)
        if min(p['width'],p['depth'],p['thickness'],gap)<=.01:
            raise ValueError('寬、深度、板厚及每格淨空須大於 0.01 公分；請增加高度、減少板厚或板片數量。')
        return p
    if style_id=='lightstrip':
        if p['width']<=.41:raise ValueError('燈條長度須大於 0.41 公分，才能保留兩端各 0.2 公分的端蓋。')
        return p
    if style_id=='handle':
        if p['width']<=style_template(style_id)['min_length_cm']:
            raise ValueError('長度至少須為 5.89 公分，才能保留兩端腳座且不重疊。')
        return p
    if style_id in THRESHOLD_STYLES:
        if p['depth']<=4.01 or p['width']<=.01:
            raise ValueError('深度須大於 4.01 公分，長度須大於 0.01 公分，才能保留門檻圓角與斜面。')
        return p
    if style_id in MOLDING_STYLES:
        band=style_template(style_id)['corner_band_cm']
        if min(p['width'],p['height'])<=2*band+.01:
            raise ValueError('寬、高都須大於 {:.2f} 公分，才能保留線板轉角。'.format(2*band+.01))
        return p
    if style_id=='boxdoor':
        if p['recess']>2.98 or min(p['width']-.4-2*p['side'],p['height']-.4-2*p['rail'])<=.01:
            raise ValueError('內凹深度須為 0～2.98 公分，且上下、左右框寬須保留中央板開口。')
        return p
    if style_id=='glassdoor':
        if p['belly']<=4:
            raise ValueError('下肚高度（含線板）須大於 4 公分，才能保留上下兩端的線板轉角。')
        if p['rows']!=int(p['rows']) or not 1<=p['rows']<=100:
            raise ValueError('格子行數請輸入 1～100 的整數。')
        p['rows']=int(p['rows']);gw=p['width']-2*p['side'];gh=p['height']-2*p['rail']-p['mid']-p['belly']
        if (gw-4.4)/2<=1.6 or (gh-2-2.4*(p['rows']-1))/p['rows']<=1.6:
            raise ValueError('尺寸不足以容納玻璃導角；請減少行數、框寬或中段，或增加寬高。')
        return p
    if style_id=='door058_two':
        if p['belly']<=4 or p['width']-2*p['side']<=4 or p['height']-2*p['rail']-p['mid']-p['belly']<=4:
            raise ValueError('上下兩肚含線板的高度及內框寬度都須大於 4 公分，才能保留原始線板轉角。')
        return p
    if style_id=='door058_three':
        upper=p['height']-2*p['rail']-p['mid1']-p['mid2']-p['belly']-p['belly2']
        if min(p['belly'],p['belly2'],upper,p['width']-2*p['side'])<=4:
            raise ValueError('三肚含線板的高度及內框寬度都須大於 4 公分，才能保留原始線板轉角。')
        return p
    if style_id in DOOR058_STYLES:
        if p['width']-2*p['side']<=4 or p['height']-2*p['rail']<=4:
            raise ValueError('寬須大於左右框寬兩倍加 4 公分，高須大於上下框寬兩倍加 4 公分，才能保留原線板轉角。')
        return p
    if style_id=='plain_frame':
        b=p['frame_width']
        if min(b,p['depth'],p['width']-2*b,p['height']-b)<=.01:
            raise ValueError('框厚及深度須大於 0.01 公分，並保留正值的內框開口。')
        return p
    if style_id in REBATE_STYLES:
        b,rw,rd=p['frame_width'],p['rebate_width'],p['rebate_depth']
        if b-rw<=.01 or p['depth']-2*rd<=.01 or p['width']-2*b<=.01 or p['height']-b<=.01:
            raise ValueError('框條寬度須大於內口寬度，總深度須大於內口深度兩倍，並保留正值的內框開口。')
        return p
    if style_id in FRAME058_STYLES:
        if p['depth']<=4:
            raise ValueError('門框深度必須大於 4 公分，才能保留前後兩側的原始造型。')
        b=p['frame_width']
        if b<=2 or p['width']-2*b<=.01 or p['height']-b<=2:
            raise ValueError('框條寬度必須大於 2 公分；整體寬須大於框條寬度兩倍，高須大於框條寬度加 2 公分。')
        return p
    if style_id in GRID_STYLES:
        if p['rows'] != int(p['rows']) or not 1<=p['rows']<=100:
            raise ValueError('格子行數請輸入 1～100 的整數。')
        p['rows']=int(p['rows'])
        minimum=1.6 if style_id=='grid' else .01
        if (p['width']-4.4)/2<=minimum or (p['height']-2-2.4*(p['rows']-1))/p['rows']<=minimum:
            raise ValueError('尺寸不足以容納原始玻璃導角；請減少行數或增加寬高。')
        return p
    if style_id == 'country':
        if min(p['side'],p['rail']) <= .8:
            raise ValueError('左右、上下框寬必須大於 0.8 公分，才能保留兩側各 0.4 公分導角。')
        if p['width']-.4-2*p['side'] <= .8 or p['height']-.4-2*p['rail'] <= .01:
            raise ValueError('框寬過大；請保留中央板開口與橫框兩端的導角空間。')
        return p
    if p['width'] - 0.4 - 2 * p['side'] <= 4:
        raise ValueError('寬必須大於「左右 × 2 + 4.4」公分，才能容納原始飾條。')
    if style_id == 'two':
        if p['belly'] <= 4:
            raise ValueError('下肚必須大於 4 公分，才能容納原始飾條。')
        if p['height']-.4-2*p['rail']-p['mid']-p['belly'] <= 4:
            raise ValueError('高必須大於「上下 × 2 + 中檔 + 下肚 + 4.4」公分。')
    elif style_id == 'three':
        if min(p['belly'],p['belly2']) <= 4:
            raise ValueError('下肚、中肚都必須大於 4 公分，才能容納原始飾條。')
        if p['height']-.4-2*p['rail']-p['mid1']-p['mid2']-p['belly']-p['belly2'] <= 4:
            raise ValueError('高必須大於「上下 × 2 + 中檔1 + 中檔2 + 下肚 + 中肚 + 4.4」公分。')
    elif p['height'] - 0.4 - 2 * p['rail'] <= 4:
        raise ValueError('高必須大於「上下 × 2 + 4.4」公分，才能容納原始飾條。')
    return p


def _number(formula, context):
    """Only numeric arithmetic and named attribute references; never eval."""
    def ref(match):
        return repr(float(context[match[1].lower()][match[2].lower()]))
    expr = re.sub(r'([A-Za-z_0-9]+)!([A-Za-z_][A-Za-z_0-9]*)', ref, str(formula))
    ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    def visit(n):
        if isinstance(n, ast.Constant) and type(n.value) in (float, int): return float(n.value)
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.USub, ast.UAdd)):
            return -visit(n.operand) if isinstance(n.op, ast.USub) else visit(n.operand)
        if isinstance(n, ast.BinOp) and type(n.op) in ops:
            return ops[type(n.op)](visit(n.left), visit(n.right))
        raise ValueError('Unsupported template expression')
    result = visit(ast.parse(expr, mode='eval').body)
    if not math.isfinite(result): raise ValueError('Invalid geometry dimension')
    return result


def shelves_geometry(p):
    """N identical solids with N+1 equal clear gaps inside the guide box."""
    w,dep,thick=p['width']/100,p['depth']/100,p['thickness']/100
    count=int(p['count']);gap=(p['height']/100-count*thick)/(count+1);parts=[]
    loops=[[0,3,2,1],[4,5,6,7],[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7]]
    pairs=[(0,1),(1,2),(2,3),(3,0),(4,5),(5,6),(6,7),(7,4),(0,4),(1,5),(2,6),(3,7)]
    for i in range(count):
        lo=gap+i*(gap+thick);hi=lo+thick
        vertices=[[0,0,lo],[w,0,lo],[w,dep,lo],[0,dep,lo],
                  [0,0,hi],[w,0,hi],[w,dep,hi],[0,dep,hi]]
        parts.append({'name':'shelf_'+str(i+1).zfill(3),'vertices':vertices,
                      'faces':[[loop] for loop in loops],'edges':[[a,b,False,False] for a,b in pairs]})
    return parts


def hangingrail_material():
    """Unpack the original SKP texture to a content-addressed local cache."""
    from pathlib import Path
    import tempfile,hashlib
    t=STYLES['hangingrail'];tex=t['texture']
    path=Path(tempfile.gettempdir())/'ingetrazo_parametric_assets'/(tex['sha256']+'.jpg')
    data=base64.b64decode(tex['base64'])
    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=tex['sha256']:
        path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
    recipe=copy.deepcopy(t['material']);recipe['texture']={'path':str(path),'sw':tex['sw'],'sh':tex['sh']}
    return recipe


def hangingrail_geometry(p):
    t=STYLES['hangingrail'];old=t['source_width_cm'];band=t['end_band_cm'];parts=[]
    recipe=hangingrail_material()
    for src in t['parts']:
        vertices=[]
        for x,y,z in src['vertices']:
            if src['name'].endswith('_P3'):x+=p['width']-old
            elif src['name'].endswith('_P2'):x=band+(x-band)*(p['width']-2*band)/(old-2*band)
            vertices.append([x/100,y/100,z/100])
        faces=copy.deepcopy(src['faces']);volume=0.
        for loops in faces:
            a=vertices[loops[0][0]]
            for ib,ic in zip(loops[0][1:],loops[0][2:]):
                b,c=vertices[ib],vertices[ic]
                volume+=sum(a[k]*(b[(k+1)%3]*c[(k+2)%3]-b[(k+2)%3]*c[(k+1)%3]) for k in range(3))
        if volume<0:faces=[[list(reversed(loop)) for loop in face] for face in faces]
        parts.append({'name':src['name'],'vertices':vertices,'faces':faces,'edges':src['edges'],
                      'material':{'mat':recipe['name'],**{k:copy.deepcopy(recipe[k]) for k in ('color','opacity','texture')}}})
    return parts


def lightstrip_geometry(p):
    t=STYLES['lightstrip'];parts=[];band=t['end_band_cm'];old=t['source_width_cm']
    def stretch(x):
        if x<=band+1e-7:return x
        if x>=old-band-1e-7:return x+p['width']-old
        return band+(x-band)*(p['width']-2*band)/(old-2*band)
    for src in t['parts']:
        vertices=[[stretch(x)/100,y/100,z/100] for x,y,z in src['vertices']]
        faces=copy.deepcopy(src['faces']);volume=0.
        for loops in faces:
            a=vertices[loops[0][0]]
            for ib,ic in zip(loops[0][1:],loops[0][2:]):
                b,c=vertices[ib],vertices[ic]
                volume+=sum(a[k]*(b[(k+1)%3]*c[(k+2)%3]-b[(k+2)%3]*c[(k+1)%3]) for k in range(3))
        if volume<0:faces=[[list(reversed(loop)) for loop in face] for face in faces]
        parts.append({'name':src['name'],'vertices':vertices,'faces':faces,'edges':src['edges'],'face_attrs':src['face_attrs']})
    return parts


def handle_geometry(p):
    """Extend the bar along X; translate the right support without scaling it."""
    t=STYLES['handle'];parts=[]
    for src in t['parts']:
        vertices=[]
        for x,y,z in src['vertices']:
            if src['name']=='handle_P3':x=x*p['width']/t['source_width_cm']
            elif src['name']=='handle_P2':x+=p['width']-t['source_width_cm']
            vertices.append([x/100,y/100,z/100])
        faces=copy.deepcopy(src['faces']);volume=0.
        for loops in faces:
            a=vertices[loops[0][0]]
            for ib,ic in zip(loops[0][1:],loops[0][2:]):
                b,c=vertices[ib],vertices[ic]
                volume+=sum(a[k]*(b[(k+1)%3]*c[(k+2)%3]-b[(k+2)%3]*c[(k+1)%3]) for k in range(3))
        if volume<0:faces=[[list(reversed(loop)) for loop in face] for face in faces]
        parts.append({'name':src['name'],'vertices':vertices,'faces':faces,'edges':src['edges']})
    return parts


def threshold_geometry(p,style_id):
    """Keep both shaped edge profiles intact; vary length and flat middle depth."""
    t=STYLES[style_id];front,back=t['front_band_cm'],t['back_band_cm'];old=t['source_depth_cm'];parts=[]
    def depth(y):
        if y<=front+1e-7:return y
        if y>=old-back-1e-7:return y+p['depth']-old
        return front+(y-front)*(p['depth']-front-back)/(old-front-back)
    for src in t['parts']:
        vertices=[[x*p['width']/t['source_width_cm']/100,depth(y)/100,z/100] for x,y,z in src['vertices']]
        faces=copy.deepcopy(src['faces']);volume=0.
        for loops in faces:
            a=vertices[loops[0][0]]
            for ib,ic in zip(loops[0][1:],loops[0][2:]):
                b,c=vertices[ib],vertices[ic]
                volume+=sum(a[k]*(b[(k+1)%3]*c[(k+2)%3]-b[(k+2)%3]*c[(k+1)%3]) for k in range(3))
        if volume<0:faces=[[list(reversed(loop)) for loop in face] for face in faces]
        parts.append({'name':src['name'],'vertices':vertices,'faces':faces,'edges':src['edges']})
    return parts


def molding_geometry(p,style_id):
    """Preserve all source corner vertices and profiles; stretch straight runs."""
    t=STYLES[style_id];band=t['corner_band_cm'];parts=[]
    def stretch(v,old,new):
        if v<=band+1e-7:return v
        if v>=old-band-1e-7:return v+new-old
        return band+(v-band)*(new-2*band)/(old-2*band)
    for src in t['parts']:
        vertices=[[stretch(x,t['source_width_cm'],p['width'])/100,y/100,
                   stretch(z,t['source_height_cm'],p['height'])/100] for x,y,z in src['vertices']]
        faces=copy.deepcopy(src['faces']);volume=0.
        for loops in faces:
            a=vertices[loops[0][0]]
            for ib,ic in zip(loops[0][1:],loops[0][2:]):
                b,c=vertices[ib],vertices[ic]
                volume+=sum(a[k]*(b[(k+1)%3]*c[(k+2)%3]-b[(k+2)%3]*c[(k+1)%3]) for k in range(3))
        if volume<0:faces=[[list(reversed(loop)) for loop in face] for face in faces]
        parts.append({'name':src['name'],'vertices':vertices,'faces':faces,'edges':src['edges']})
    return parts


def boxdoor_geometry(p):
    """Source topology; fixed 3 cm back plane, adjustable front recess."""
    t=STYLES['boxdoor'];parts=[]
    def span(v,old,new,ob,nb):
        if v<=.2+ob+1e-7:return .2+(v-.2)*nb/ob
        if v>=old-.2-ob-1e-7:return new-.2-(old-.2-v)*nb/ob
        return .2+nb+(v-.2-ob)*(new-.4-2*nb)/(old-.4-2*ob)
    for source in t['parts']:
        panel=source['name']=='Mouth_doorP9'
        vertices=[]
        for x,y,z in source['vertices']:
            yy=p['recess']+(y-1.1)*(3-p['recess'])/.9 if panel else y*1.5
            vertices.append([span(x,t['source_width_cm'],p['width'],12,p['side'])/100,
                             yy/100,span(z,t['source_height_cm'],p['height'],14,p['rail'])/100])
        faces=copy.deepcopy(source['faces']);volume=0.
        for loops in faces:
            a=vertices[loops[0][0]]
            for ib,ic in zip(loops[0][1:],loops[0][2:]):
                b,c=vertices[ib],vertices[ic]
                volume+=sum(a[k]*(b[(k+1)%3]*c[(k+2)%3]-b[(k+2)%3]*c[(k+1)%3]) for k in range(3))
        if volume<0:faces=[[list(reversed(loop)) for loop in face] for face in faces]
        edges=copy.deepcopy(source['edges'])
        for e in edges:
            if all(abs(vertices[i][1])<1e-8 and abs(vertices[i][2]-.002)<1e-8 for i in e[:2]):e[2:]=[False,False]
        parts.append({'name':source['name'],'vertices':vertices,'faces':faces,'edges':edges})
    return parts


def country_geometry(p):
    """Stretch only flat spans; all 4 mm bevel bands keep their original shape."""
    t=STYLES['country'];bevel=t['bevel_cm'];parts=[]
    def stretch(value,old,new):
        if value<=bevel+1e-8:return value
        if value>=old-bevel-1e-8:return value+new-old
        return bevel+(value-bevel)*(new-2*bevel)/(old-2*bevel)
    w,h,side,rail=(p[k] for k in ('width','height','side','rail'))
    for direction in ('bottom','top','left','right'):
        source=t['strip'];horizontal=direction in ('bottom','top')
        length=w-.4-2*side if horizontal else h-.4
        breadth=rail if horizontal else side
        vertices=[]
        for x,y,z in source['vertices']:
            x=stretch(x,t['strip_length_cm'],length)
            z=stretch(z,t['strip_width_cm'],breadth)
            if direction=='bottom':v=[side+.2+x,y,.2+z]
            elif direction=='top':v=[side+.2+x,y,h-.2-z]
            elif direction=='left':v=[side+.2-z,y,.2+x]
            else:v=[w-.2-z,y,.2+x]
            vertices.append([a/100 for a in v])
        parts.append({'name':'country_frame_'+direction,'vertices':vertices,
                      'faces':source['faces'],'edges':source['edges']})
    source=t['panel'];base=t['defaults']
    vertices=[[(side+.2+x*(w-.4-2*side)/(base['width']-.4-2*base['side']))/100,
               y/100,(rail+.2+z*(h-.4-2*rail)/(base['height']-.4-2*base['rail']))/100]
              for x,y,z in source['vertices']]
    parts.append({'name':'country_panel','vertices':vertices,'faces':source['faces'],'edges':source['edges']})
    # Reflected top frame needs reversed winding for outward surface normals.
    for part in parts:
        volume=0.
        for loops in part['faces']:
            vs=[part['vertices'][i] for i in loops[0]];a=vs[0]
            for b,c in zip(vs[1:],vs[2:]):
                volume+=a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0])
        if volume<0:part['faces']=[[list(reversed(loop)) for loop in face] for face in part['faces']]
        part['edges']=[list(e) for e in part['edges']]
        for edge in part['edges']:
            if all(abs(part['vertices'][i][1])<1e-8 and abs(part['vertices'][i][2]-.002)<1e-8 for i in edge[:2]):edge[2:]=[False,False]
    return parts


def grid_geometry(p,style_id='grid',template=None):
    t=template if template is not None else STYLES[style_id];w,h,rows=p['width'],p['height'],int(p['rows']);parts=[]
    pw=(w-4.4)/2;ph=(h-2-2.4*(rows-1))/rows
    def stretch(value,old,new,band):
        if value<=band+1e-8:return value
        if value>=old-band-1e-8:return value+new-old
        return band+(value-band)*(new-2*band)/(old-2*band)
    def part(source,name,vertices):
        parts.append({'name':name,'vertices':[[v/100 for v in xyz] for xyz in vertices],
                      'faces':source['faces'],'edges':source['edges'],
                      'material':source.get('material',{'color':[242/255]*3,'opacity':1.})})
    for source in t['frame']:
        part(source,'grid_'+source['name'],[
            [stretch(x,t['source_width_cm'],w,1),y,stretch(z,t['source_height_cm'],h,1)]
            for x,y,z in source['vertices']])
    source=t['vertical']
    part(source,'grid_vertical',[[w/2+x,y,1+z*(h-2)/(t['source_height_cm']-2)] for x,y,z in source['vertices']])
    for row in range(rows-1):
        source=t['horizontal'];zbase=1+ph+row*(ph+2.4)
        part(source,'grid_horizontal_'+str(row+1),[[1+x*(w-2)/(t['source_width_cm']-2),y,zbase+z] for x,y,z in source['vertices']])
    if 'back_glass' in t:
        source=t['back_glass']
        part(source,'grid_back_glass',[[x*w/t['source_width_cm'],y,z*h/t['source_height_cm']] for x,y,z in source['vertices']])
        return parts
    for row in range(rows):
        zbase=1+row*(ph+2.4)
        for side,xbase in [('left',1),('right',w/2+1.2)]:
            source=t['glass_'+side]
            part(source,'grid_glass_'+side+'_'+str(row+1),[
                [xbase+stretch(x,t['pane_width_cm'],pw,.8),y,zbase+stretch(z,t['pane_height_cm'],ph,.8)]
                for x,y,z in source['vertices']])
    return parts


def louver_params(params):
    p=dict(params)
    # Old unequal rails become their mean: preserve total frame area/opening height.
    p.setdefault('rail',(p.get('top_rail',14.)+p.get('bottom_rail',14.))/2)
    p.setdefault('side',5.)
    p.pop('top_rail',None);p.pop('bottom_rail',None)
    return p


def louver_regions(p):
    bottom,top=p['rail'],p['height']-p['rail']
    if not p.get('show_mid',True):return [('full',bottom,top)]
    center=bottom+(top-bottom)*p['mid_position']/100
    return [('lower',bottom,center-p['mid']/2),('upper',center+p['mid']/2,top)]


def louver_layout(p):
    pitch=STYLES['louverdoor']['pitch_cm'];out=[]
    for name,lo,hi in louver_regions(p):
        count=max(0,int(math.floor((hi-lo+1e-9)/pitch)))
        step=(hi-lo)/count if count else 0.
        out.append((name,lo,hi,count,step))
    return out


def louver_geometry(p):
    t=STYLES['louverdoor'];ow,oh=t['source_width_cm'],t['source_height_cm'];w,h,side=p['width'],p['height'],p['side'];parts=[]
    def stretch(value,old,new,band):
        if value<=band+1e-7:return value
        if value>=old-band-1e-7:return value+new-old
        return band+(value-band)*(new-2*band)/(old-2*band)
    def append(src,name,mapper):
        parts.append({'name':name,'vertices':[[a/100 for a in mapper(*v)] for v in src['vertices']],
                      'faces':src['faces'],'edges':src['edges']})
    for i,src in enumerate(t['frame']):
        if i<3 or i>=9:
            def mapped(x,y,z):return ((w-side if i>=9 else 0)+stretch(x-(ow-5 if i>=9 else 0),5,side,.5),y-t['front_cm'],stretch(z,oh,h,2))
        else:
            is_top=i>=6;old_start=oh-14 if is_top else 0;new_size=p['rail'];new_start=h-new_size if is_top else 0
            def mapped(x,y,z):return (side+stretch(x-5,ow-10,w-2*side,2),y-t['front_cm'],new_start+stretch(z-old_start,14,new_size,.5))
        append(src,'louver_frame_'+str(i),mapped)
    if p.get('show_mid',True):
        bottom,top=p['rail'],h-p['rail'];center=bottom+(top-bottom)*p['mid_position']/100
        for i,src in enumerate(t['middle']):
            append(src,'louver_middle_'+str(i),lambda x,y,z:(side+stretch(x-5,t['source_middle_width_cm'],w-2*side,2),y-t['front_cm'],center-p['mid']/2+stretch(z-t['source_middle_z_cm'],10,p['mid'],.5)))
    cy,cz=t['blade_center_cm'];angle=math.radians(90*(1-p['opening']/100)-t['blade_angle_degrees']);co,si=math.cos(angle),math.sin(angle)
    for name,lo,hi,count,step in louver_layout(p):
        for n in range(count):
            center=lo+(n+.5)*step
            append(t['blade'],'louver_blade_'+name+'_'+str(n+1).zfill(3),
                   lambda x,y,z:(side+(x-5)*(w-2*side)/(ow-10),cy+(y-cy)*co-(z-cz)*si-t['front_cm'],center+(y-cy)*si+(z-cz)*co))
    return parts


def emptycabinet_geometry(p):
    """Original five-board construction; sides full height, back flush with rear."""
    w,h,dep,b,bt=[p[k]/100 for k in ('width','height','depth','thickness','back_thickness')];parts=[]
    loops=[[0,3,2,1],[4,5,6,7],[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7]]
    pairs=[(0,1),(1,2),(2,3),(3,0),(4,5),(5,6),(6,7),(7,4),(0,4),(1,5),(2,6),(3,7)]
    for name,x0,y0,z0,x1,y1,z1 in [('back',b,dep-bt,b,w-b,dep,h-b),('bottom',b,0,0,w-b,dep,b),
                                 ('left',0,0,0,b,dep,h),('top',b,0,h-b,w-b,dep,h),('right',w-b,0,0,w,dep,h)]:
        vertices=[[x0,y0,z0],[x1,y0,z0],[x1,y1,z0],[x0,y1,z0],
                  [x0,y0,z1],[x1,y0,z1],[x1,y1,z1],[x0,y1,z1]]
        parts.append({'name':'emptycabinet_'+name,'vertices':vertices,'faces':[[loop] for loop in loops],
                      'edges':[[a,c,False,False] for a,c in pairs]})
    return parts


def plain_frame_geometry(p):
    w,h,dep,b=[p[k]/100 for k in ('width','height','depth','frame_width')];parts=[]
    loops=[[0,3,2,1],[4,5,6,7],[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7]]
    pairs=[(0,1),(1,2),(2,3),(3,0),(4,5),(5,6),(6,7),(7,4),(0,4),(1,5),(2,6),(3,7)]
    for name,x0,x1,z0,z1 in [('left',0,b,0,h-b),('right',w-b,w,0,h-b),('top',0,w,h-b,h)]:
        vertices=[[x0,0,z0],[x1,0,z0],[x1,dep,z0],[x0,dep,z0],
                  [x0,0,z1],[x1,0,z1],[x1,dep,z1],[x0,dep,z1]]
        parts.append({'name':'plain_frame_'+name,'vertices':vertices,'faces':[[loop] for loop in loops],
                      'edges':[[a,c,False,False] for a,c in pairs]})
    return parts


def frame_geometry(p,style_id):
    """Keep the source 20 mm corner/profile band; stretch only flat spans."""
    t=STYLES[style_id];w,h,b=p['width'],p['height'],p['frame_width']
    ow,oh,ob=t['source_width_cm'],t['source_height_cm'],t['source_frame_width_cm']
    band=t['profile_band_cm'];depth=p.get('depth',12);parts=[]
    def edge_distance(v):
        if v<=ob-band+1e-7:return v*(b-band)/(ob-band)
        return v+b-ob
    def xmap(x):
        if x<=ob+1e-7:return edge_distance(x)
        if x>=ow-ob-1e-7:return w-edge_distance(ow-x)
        return b+(x-ob)*(w-2*b)/(ow-2*ob)
    def zmap(z):
        down=oh-z
        if down<=ob+1e-7:return h-edge_distance(down)
        return (h-b)*z/(oh-ob)
    for section in ('body','front','back'):
        if section=='back' and style_id=='frame_single':continue
        for source in t[section]:
            vertices=[]
            for x,y,z in source['vertices']:
                # Translate the rear moulding intact. Only the core changes depth.
                if section=='back':y+=depth-12
                elif section=='body':
                    inner=source['name'].rsplit('_',1)[-1] in ('p6','p7','p8','p9','p10')
                    if inner:y=2+(y-2)*(depth-(2 if style_id=='frame_single' else 4))/8
                    else:y=y*depth/12
                vertices.append([xmap(x)/100,y/100,zmap(z)/100])
            edges=[list(e) for e in source['edges']]
            if style_id=='frame_single' and section=='body':
                for e in edges:
                    vv=[vertices[i] for i in e[:2]]
                    if all(abs(v[1]-depth/100)<1e-7 for v in vv):
                        inner=(all(abs(v[0]-b/100)<1e-7 and v[2]<=(h-b)/100+1e-7 for v in vv)
                               or all(abs(v[0]-(w-b)/100)<1e-7 and v[2]<=(h-b)/100+1e-7 for v in vv)
                               or all(abs(v[2]-(h-b)/100)<1e-7 for v in vv))
                        outer=any(all(abs(v[axis]-value)<1e-7 for v in vv) for axis,value in ((0,0),(0,w/100),(2,0),(2,h/100)))
                        e[2:]=[False,not (inner or outer)]
            # Reflected source back pieces have inward winding; orient each solid outwards.
            faces=source['faces'];volume=0.
            for loops in faces:
                for loop in loops:
                    a=vertices[loop[0]]
                    for ib,ic in zip(loop[1:],loop[2:]):
                        bb,cc=vertices[ib],vertices[ic]
                        volume+=sum(a[k]*(bb[(k+1)%3]*cc[(k+2)%3]-bb[(k+2)%3]*cc[(k+1)%3]) for k in range(3))
            if volume<0:faces=[[list(reversed(loop)) for loop in face] for face in faces]
            parts.append({'name':'frame_'+section+'_'+source['name'].rsplit('/',1)[-1],
                          'vertices':vertices,'faces':faces,'edges':edges})
    return parts


def rebate_geometry(p,style_id):
    """Independent rebate width/depth; resize the original ten source solids."""
    t=STYLES[style_id];ow,oh=t['source_width_cm'],t['source_height_cm']
    w,h,b,depth,rw,rd=(p[k] for k in ('width','height','frame_width','depth','rebate_width','rebate_depth'))
    def edge_distance(v):
        if v<=3+1e-7:return v*(b-rw)/3
        return b-rw+(v-3)*rw/2
    def xmap(x):
        if x<=5+1e-7:return edge_distance(x)
        if x>=ow-5-1e-7:return w-edge_distance(ow-x)
        return b+(x-5)*(w-2*b)/(ow-10)
    def zmap(z):
        down=oh-z
        if down<=5+1e-7:return h-edge_distance(down)
        return (h-b)*z/(oh-5)
    parts=[]
    for source in t['body']:
        inner=int(source['name'].rsplit('_P',1)[-1])>=6
        vertices=[[xmap(x)/100,
                   (rd+(y-2)*(depth-rd*(1 if style_id=='rebate_single' else 2))/16 if inner else y*depth/20)/100,
                   zmap(z)/100] for x,y,z in source['vertices']]
        faces=source['faces'];volume=0.
        for loops in faces:
            for loop in loops:
                a=vertices[loop[0]]
                for ib,ic in zip(loop[1:],loop[2:]):
                    bb,cc=vertices[ib],vertices[ic]
                    volume+=sum(a[k]*(bb[(k+1)%3]*cc[(k+2)%3]-bb[(k+2)%3]*cc[(k+1)%3]) for k in range(3))
        if volume<0:faces=[[list(reversed(loop)) for loop in face] for face in faces]
        edges=[list(e) for e in source['edges']]
        if style_id=='rebate_single':
            for e in edges:
                vv=[vertices[i] for i in e[:2]]
                if all(abs(v[1]-depth/100)<1e-7 for v in vv):
                    inside=(all(abs(v[0]-b/100)<1e-7 and v[2]<=(h-b)/100+1e-7 for v in vv)
                            or all(abs(v[0]-(w-b)/100)<1e-7 and v[2]<=(h-b)/100+1e-7 for v in vv)
                            or all(abs(v[2]-(h-b)/100)<1e-7 for v in vv))
                    outside=any(all(abs(v[axis]-value)<1e-7 for v in vv) for axis,value in ((0,0),(0,w/100),(2,0),(2,h/100)))
                    e[2:]=[False,not (inside or outside)]
        parts.append({'name':'rebate_'+source['name'],'vertices':vertices,'faces':faces,'edges':edges})
    return parts


def door058_geometry(p,style_id):
    """Resize the flat frame and panel spans; keep both 058 profiles unchanged."""
    t=STYLES[style_id];band=t['profile_band_cm'];parts=[]
    def stretch(v,old,new,oldborder,newborder):
        if v<=oldborder+1e-7:return v*newborder/oldborder
        if v>=old-oldborder-1e-7:return new-(old-v)*newborder/oldborder
        if v<=oldborder+band+1e-7:return newborder+v-oldborder
        if v>=old-oldborder-band-1e-7:return new-newborder-(old-oldborder-v)
        return newborder+band+(v-oldborder-band)*(new-2*newborder-2*band)/(old-2*oldborder-2*band)
    for source in t['parts']:
        vertices=[[stretch(x,t['source_width_cm'],p['width'],t['source_side_cm'],p['side'])/100,
                   y/100,stretch(z,t['source_height_cm'],p['height'],t['source_rail_cm'],p['rail'])/100]
                  for x,y,z in source['vertices']]
        faces=source['faces'];volume=0.
        for loops in faces:
            for loop in loops:
                a=vertices[loop[0]]
                for ib,ic in zip(loop[1:],loop[2:]):
                    bb,cc=vertices[ib],vertices[ic]
                    volume+=sum(a[k]*(bb[(k+1)%3]*cc[(k+2)%3]-bb[(k+2)%3]*cc[(k+1)%3]) for k in range(3))
        if volume<0:faces=[[list(reversed(loop)) for loop in face] for face in faces]
        edges=[list(e) for e in source['edges']]
        for e in edges:
            vv=[vertices[i] for i in e[:2]]
            if any(all(abs(v[1]-y)<1e-7 for v in vv) for y in (0,.042)) and any(all(abs(v[axis]-value)<1e-7 for v in vv) for axis,value in ((0,0),(0,p['width']/100),(2,0),(2,p['height']/100))):
                e[2:]=[False,False]
        parts.append({'name':source['name'],'vertices':vertices,'faces':faces,'edges':edges})
    return parts


def door058two_geometry(p):
    t=STYLES['door058_two'];w,h,side,rail,belly=(p[k] for k in ('width','height','side','rail','belly'))
    mid=p['mid'];parts=[]
    def xmap(x):
        if x<=12+1e-7:return x*side/12
        if x>=83-1e-7:return w-(95-x)*side/12
        if x<=14+1e-7:return side+x-12
        if x>=81-1e-7:return w-side-(83-x)
        return side+2+(x-14)*(w-2*side-4)/67
    oldz=(0,14,59,79,286,300);newz=(0,rail,rail+belly,rail+belly+mid,h-rail,h)
    def body_z(z):
        for a,b,c,dd in zip(oldz,oldz[1:],newz,newz[1:]):
            if z<=b+1e-7:return c+(z-a)*(dd-c)/(b-a)
        return h
    def mould_z(z,section):
        lower=section.startswith('lower');oldstart=14 if lower else 79;oldheight=45 if lower else 207
        start=rail if lower else rail+belly+mid;height=belly if lower else h-2*rail-belly-mid
        local=z-oldstart
        if local<=2+1e-7:return start+local
        if local>=oldheight-2-1e-7:return start+height-(oldheight-local)
        return start+2+(local-2)*(height-4)/(oldheight-4)
    for source in t['parts']:
        section=source['section']
        vertices=[[xmap(x)/100,y/100,(body_z(z) if section=='body' else mould_z(z,section))/100] for x,y,z in source['vertices']]
        faces=source['faces'];volume=0.
        for loops in faces:
            for loop in loops:
                a=vertices[loop[0]]
                for ib,ic in zip(loop[1:],loop[2:]):
                    bb,cc=vertices[ib],vertices[ic]
                    volume+=sum(a[k]*(bb[(k+1)%3]*cc[(k+2)%3]-bb[(k+2)%3]*cc[(k+1)%3]) for k in range(3))
        if volume<0:faces=[[list(reversed(loop)) for loop in face] for face in faces]
        edges=[list(e) for e in source['edges']]
        for e in edges:
            vv=[vertices[i] for i in e[:2]]
            if any(all(abs(v[1]-yy)<1e-7 for v in vv) for yy in (0,.042)) and any(all(abs(v[a]-v0)<1e-7 for v in vv) for a,v0 in ((0,0),(0,w/100),(2,0),(2,h/100))):e[2:]=[False,False]
        parts.append({'name':source['name'],'vertices':vertices,'faces':faces,'edges':edges})
    return parts


def door058three_geometry(p):
    t=STYLES['door058_three'];w,h,side,rail,q1,q2,b1,b2=(p[k] for k in ('width','height','side','rail','mid1','mid2','belly','belly2'))
    parts=[]
    def xmap(x):
        if x<=7+1e-7:return x*side/7
        if x>=53-1e-7:return w-(60-x)*side/7
        if x<=9+1e-7:return side+x-7
        if x>=51-1e-7:return w-side-(53-x)
        return side+2+(x-9)*(w-2*side-4)/42
    oldz=(0,9,45,54,72,81,187.5,196.5)
    newz=(0,rail,rail+b1,rail+b1+q1,rail+b1+q1+b2,rail+b1+q1+b2+q2,h-rail,h)
    def body_z(z):
        for a,b,c,dd in zip(oldz,oldz[1:],newz,newz[1:]):
            if z<=b+1e-7:return c+(z-a)*(dd-c)/(b-a)
        return h
    def mould_z(z,section):
        index={'lower':0,'middle':1,'upper':2}[section]
        oldstart=(9,54,81)[index];oldheight=(36,18,106.5)[index]
        start=(rail,rail+b1+q1,rail+b1+q1+b2+q2)[index]
        height=(b1,b2,h-2*rail-b1-b2-q1-q2)[index];local=z-oldstart
        if local<=2+1e-7:return start+local
        if local>=oldheight-2-1e-7:return start+height-(oldheight-local)
        return start+2+(local-2)*(height-4)/(oldheight-4)
    for source in t['parts']:
        section=source['section']
        vertices=[[xmap(x)/100,y/100,(body_z(z) if section=='body' else mould_z(z,section))/100] for x,y,z in source['vertices']]
        faces=source['faces'];volume=0.
        for loops in faces:
            for loop in loops:
                a=vertices[loop[0]]
                for ib,ic in zip(loop[1:],loop[2:]):
                    bb,cc=vertices[ib],vertices[ic]
                    volume+=sum(a[k]*(bb[(k+1)%3]*cc[(k+2)%3]-bb[(k+2)%3]*cc[(k+1)%3]) for k in range(3))
        if volume<0:faces=[[list(reversed(loop)) for loop in face] for face in faces]
        edges=[list(e) for e in source['edges']]
        for e in edges:
            vv=[vertices[i] for i in e[:2]]
            if any(all(abs(v[1]-yy)<1e-7 for v in vv) for yy in (0,.045)) and any(all(abs(v[a]-v0)<1e-7 for v in vv) for a,v0 in ((0,0),(0,w/100),(2,0),(2,h/100))):e[2:]=[False,False]
        parts.append({'name':source['name'],'vertices':vertices,'faces':faces,'edges':edges})
    return parts


def glassdoor_geometry(p):
    t=STYLES['glassdoor'];w,h,side,rail,mid=(p[k] for k in ('width','height','side','rail','mid'))
    belly=p['belly'];parts=[]
    def xmap(x):
        if x<=10+1e-7:return x*side/10
        if x>=70-1e-7:return w-(80-x)*side/10
        if x<=12+1e-7:return side+x-10
        if x>=68-1e-7:return w-side-(70-x)
        return side+2+(x-12)*(w-2*side-4)/56
    oldz=(0,12,57,69,188,200);newz=(0,rail,rail+belly,rail+belly+mid,h-rail,h)
    def body_z(z):
        for a,b,c,dd in zip(oldz,oldz[1:],newz,newz[1:]):
            if z<=b+1e-7:return c+(z-a)*(dd-c)/(b-a)
        return h
    def mould_z(z):
        local=z-12
        if local<=2+1e-7:return rail+local
        if local>=43-1e-7:return rail+belly-(45-local)
        return rail+2+(local-2)*(belly-4)/41
    for source in t['parts']:
        mould=not source['name'].startswith('glassdoor_body_')
        vertices=[[xmap(x)/100,y/100,(mould_z(z) if mould else body_z(z))/100] for x,y,z in source['vertices']]
        edges=[list(e) for e in source['edges']]
        for e in edges:
            vv=[vertices[i] for i in e[:2]]
            if any(all(abs(v[1]-yy)<1e-7 for v in vv) for yy in (0,.042)) and any(all(abs(v[a]-v0)<1e-7 for v in vv) for a,v0 in ((0,0),(0,w/100),(2,0),(2,h/100))):e[2:]=[False,False]
        parts.append({'name':source['name'],'vertices':vertices,'faces':source['faces'],'edges':edges})
    zbase=rail+belly+mid
    gp={'width':w-2*side,'height':h-rail-zbase,'rows':p['rows']}
    for part in grid_geometry(gp,template=t['grid']):
        part['vertices']=[[x+side/100,y+.0065,z+zbase/100] for x,y,z in part['vertices']]
        parts.append(part)
    # The original reflected back mouldings require outward winding.
    for part in parts:
        vs=part['vertices'];volume=0.
        for loops in part['faces']:
            for loop in loops:
                a=vs[loop[0]]
                for ib,ic in zip(loop[1:],loop[2:]):
                    bb,cc=vs[ib],vs[ic]
                    volume+=sum(a[k]*(bb[(k+1)%3]*cc[(k+2)%3]-bb[(k+2)%3]*cc[(k+1)%3]) for k in range(3))
        if volume<0:part['faces']=[[list(reversed(loop)) for loop in face] for face in part['faces']]
    return parts


def door_name(style_id):
    if style_id=='louverdoor':return '百葉門片'
    if style_id=='emptycabinet':return '空櫃'
    if style_id=='hangingrail':return '吊衣桿'
    if style_id=='plain_frame':return '素門框'
    if style_id=='lightstrip':return '燈條'
    if style_id=='shelves':return '均分層板'
    if style_id=='handle':return '一字取手'
    if style_id in THRESHOLD_STYLES:return '門檻（'+STYLES[style_id]['label']+'）'
    if style_id in MOLDING_STYLES:return '線板框（'+STYLES[style_id]['label']+'）'
    if style_id=='boxdoor':return '口框櫃門片'
    if style_id in DOOR058_STYLES:return '058門（'+STYLES[style_id]['label']+'）'
    if style_id in FRAME_STYLES:return ('企口框' if style_id in REBATE_STYLES else '058框')+'（'+STYLES[style_id]['label']+'）'
    return STYLES[style_id]['label'] if style_id in GRID_STYLES else '鄉村門片' if style_id=='country' else '058櫃門片（'+STYLES[style_id]['label']+'）'


def geometry(params, style_id='one'):
    """Return original leaf topology, with each part resized by its DC formulas.
    Inputs/working values are centimetres; output vertices are metres, Z-up.
    """
    template = style_template(style_id)
    p = validate(params,style_id)
    if style_id=='door058_three':return door058three_geometry(p)
    if style_id=='door058_two':return door058two_geometry(p)
    if style_id=='glassdoor':return glassdoor_geometry(p)
    if style_id in DOOR058_STYLES:return door058_geometry(p,style_id)
    if style_id=='louverdoor':return louver_geometry(p)
    if style_id=='emptycabinet':return emptycabinet_geometry(p)
    if style_id=='plain_frame':return plain_frame_geometry(p)
    if style_id in REBATE_STYLES:return rebate_geometry(p,style_id)
    if style_id in FRAME058_STYLES:return frame_geometry(p,style_id)
    if style_id=='shelves':return shelves_geometry(p)
    if style_id=='hangingrail':return hangingrail_geometry(p)
    if style_id=='lightstrip':return lightstrip_geometry(p)
    if style_id=='handle':return handle_geometry(p)
    if style_id in THRESHOLD_STYLES:return threshold_geometry(p,style_id)
    if style_id in MOLDING_STYLES:return molding_geometry(p,style_id)
    if style_id=='boxdoor':return boxdoor_geometry(p)
    if style_id=='country':return country_geometry(p)
    if style_id in GRID_STYLES:return grid_geometry(p,style_id)
    context = {'cabinet_door': {'lenx':p['width'], 'lenz':p['height'], 'leny':3,
                               'rightleft':p['side'], 'updown':p['rail']}}
    if style_id == 'two':
        context = {'2b_cabinet_door_all': {'lenx':p['width'],'lenz':p['height'],
                   'leny':2,'right_left':p['side'],'uo_down':p['rail'],
                   'mid':p['mid'],'belly':p['belly']}}
    elif style_id == 'three':
        context = {'3be_door': {'lenx':p['width'],'lenz':p['height'],'leny':3,
                   'rl':p['side'],'ud':p['rail'],'middle_1':p['mid1'],
                   'middle_2':p['mid2'],'belly1':p['belly'],'belly2':p['belly2']}}
    parts = []
    def walk(node, offset):
        a = node['attrs']; values = {}
        for k in ('lenx','leny','lenz','right_left','up_down','mid','belly'):
            if '_'+k+'_formula' in a:
                values[k] = _number(a['_'+k+'_formula'], context)
            elif k in a:
                values[k] = float(a[k]) * (2.54 if k.startswith('len') else 1)
        context[node.get('context_name',node['name']).lower()] = values
        location = []
        for i,k in enumerate('xyz'):
            f = a.get('_'+k+'_formula',a.get('_inst__'+k+'_formula'))
            v = _number(f, context) if f is not None else float(a.get(k,0))*2.54
            location.append(offset[i]+v)
        if node.get('vertices'):
            vertices = node['vertices']
            span = [max(v[i] for v in vertices)-min(v[i] for v in vertices) for i in range(3)]
            scale = [(node.get('fixed_spans',{}).get(k,values[k]))/span[i] if span[i]>1e-9 else 1 for i,k in enumerate(('lenx','leny','lenz'))]
            parts.append({'name':node['name'], 'vertices':[
                [(v[i]*scale[i]+location[i])/100 for i in range(3)] for v in vertices],
                'faces':node['faces'], 'edges':node['edges']})
        for ch in node['children']: walk(ch, location)
    for node in template['children']: walk(node,[0,0,0])
    # The source hides some external bottom edges as well as internal seams.
    # Show the physical front bottom contour, preserving every other flag.
    for part in parts:
        part['edges'] = [list(e) for e in part['edges']]
        for edge in part['edges']:
            endpoints = [part['vertices'][i] for i in edge[:2]]
            if all(abs(v[1]) < 1e-8 and abs(v[2]-.002) < 1e-8 for v in endpoints):
                edge[2] = False
                edge[3] = False
    return parts


def _reuse_louver_blade(old, old_params, p):
    """Keep per-blade topology/paint and GPU mesh caches during linear edits.
    Never mutate an old mesh: history snapshots still own those same meshes.
    """
    if old is None or not old.name.startswith('louver_blade_'):return None
    if old_params.get('opening')!=p['opening']:return None
    from PySide6.QtGui import QMatrix4x4
    def center(params):
        for name,lo,hi,count,step in louver_layout(params):
            prefix='louver_blade_'+name+'_'
            if old.name.startswith(prefix):
                index=int(old.name[len(prefix):])-1
                if index<count:return lo+(index+.5)*step
        return None
    before,after=center(old_params),center(p)
    if before is None or after is None:return None
    m=QMatrix4x4();m.translate(p['side']/100,0,after/100)
    m.scale((p['width']-2*p['side'])/(old_params['width']-2*old_params['side']),1,1)
    m.translate(-old_params['side']/100,0,-before/100)
    child=copy.copy(old)
    child.xform=m*old.xform if old.xform is not None else m
    return child


def build_group(params, previous=None, style_id=None):
    from PySide6.QtGui import QVector3D, QMatrix4x4
    from core.group import Group, group_frame
    from core.mesh import Mesh, PAINT_KEYS
    style_id = style_id or style_of(previous)
    template = style_template(style_id)
    p = validate(params,style_id)
    children = []
    old_parts = {g.name:g for g in getattr(previous,'children',[]) or []}
    old_louver=(validate(previous.ext[KEY]['params_cm'],'louverdoor')
                if previous is not None and style_id=='louverdoor' and style_of(previous)=='louverdoor' else None)
    for part in geometry(p,style_id):
        if old_louver is not None:
            reused=_reuse_louver_blade(old_parts.get(part['name']),old_louver,p)
            if reused is not None:
                children.append(reused);continue
        mesh = Mesh()
        pts = [QVector3D(*v) for v in part['vertices']]
        # Source 2 has a 0.01 mm backing skin, below the host's weld tolerance.
        # Remove only collapsed loops/edges after welding, retaining its visible face.
        welded=[mesh.vertex(pt) for pt in pts]
        def clean_loop(indices):
            loop=[]
            for i in indices:
                v=welded[i]
                if not loop or loop[-1] is not v:loop.append(v)
            if len(loop)>1 and loop[-1] is loop[0]:loop.pop()
            return [v.position for v in loop] if len(set(loop))>=3 else []
        for face_index,loops in enumerate(part['faces']):
            outer=clean_loop(loops[0])
            if outer:
                face=mesh.add_face(outer,[hole for ids in loops[1:] if (hole:=clean_loop(ids))])
                if face is not None and 'face_attrs' in part:face.attrs.update(copy.deepcopy(part['face_attrs'][face_index]))
        glass_flags={} if style_id in ('grid','glassdoor') and part['name'].startswith('grid_glass_') else None
        for ia,ib,soft,hidden in part['edges']:
            if welded[ia] is welded[ib]:continue
            edge = mesh.add_edge(pts[ia],pts[ib])
            if glass_flags is not None:
                # Adjacent source pieces repeat a bevel boundary with different flags.
                # A visible boundary must survive regardless of source-piece order.
                prev=glass_flags.get(edge,(True,True))
                glass_flags[edge]=(prev[0] and bool(soft),prev[1] and bool(hidden))
                edge.soft,edge.hidden=glass_flags[edge]
            else:edge.soft=bool(soft);edge.hidden=bool(hidden)
        if style_id in ('country','glassdoor',*GRID_STYLES):
            # Match the large planar faces to the bevel strips' subdivisions.
            while True:
                split=False
                for edge in list(mesh.edges):
                    mid=mesh.interior_vertex_on(edge) if len(edge.faces)==1 else None
                    if mid is not None:
                        rec=mesh.split_edge_at(edge,mid)
                        for key in ('e0','e1'):
                            if rec[key+'_new']:rec[key].hidden=edge.hidden
                        split=True;break
                if not split:break
        child = Group(mesh,part['name'])
        if 'material' in part:child.material=copy.deepcopy(part['material'])
        old = old_parts.get(part['name'])
        if old is not None:
            for key in ('material','layer','hidden','ifc'):
                setattr(child,key,copy.deepcopy(getattr(old,key,None)))
            for face,oldface in zip(child.mesh.faces,old.mesh.faces):
                face.attrs.update({k:copy.deepcopy(v) for k,v in oldface.attrs.items() if k in PAINT_KEYS})
        children.append(child)
    if style_id=='handle':
        # Original mounting-plane cross, with a real vertex at the exact center.
        guide_mesh=Mesh()
        cx,back,cz=p['width']/200,template['depth_cm']/100,template['height_cm']/200
        center=QVector3D(cx,back,cz)
        for endpoint in (QVector3D(cx-.02,back,cz),QVector3D(cx+.02,back,cz),
                         QVector3D(cx,back,0),QVector3D(cx,back,2*cz)):
            guide_mesh.add_edge(center,endpoint)
        children.append(Group(guide_mesh,'取手中心定位線'))
    if style_id=='shelves':
        guide_mesh=Mesh();w,dep,h=p['width']/100,p['depth']/100,p['height']/100
        corners=[QVector3D(0,0,0),QVector3D(w,0,0),QVector3D(w,dep,0),QVector3D(0,dep,0),
                 QVector3D(0,0,h),QVector3D(w,0,h),QVector3D(w,dep,h),QVector3D(0,dep,h)]
        for a,b in ((0,1),(1,2),(2,3),(3,0),(4,5),(5,6),(6,7),(7,4),(0,4),(1,5),(2,6),(3,7)):
            guide_mesh.add_edge(corners[a],corners[b])
        guide=Group(guide_mesh,'層板範圍定位線框');guide.hidden=p['hide_guide']
        children.append(guide)
    if style_id=='hangingrail':
        # Source front and bottom planes stay fixed; back/top distances are from the rod axis.
        guide_mesh=Mesh();w=p['width']/100
        front=(3.5-template['front_guide_cm'])/100;back=(3.5+p['guide_back'])/100;top=(3.5+p['guide_top'])/100
        corners=[QVector3D(0,front,0),QVector3D(w,front,0),QVector3D(w,back,0),QVector3D(0,back,0),
                 QVector3D(0,front,top),QVector3D(w,front,top),QVector3D(w,back,top),QVector3D(0,back,top)]
        for a,b in ((0,1),(1,2),(2,3),(3,0),(4,5),(5,6),(6,7),(7,4),(0,4),(1,5),(2,6),(3,7)):
            guide_mesh.add_edge(corners[a],corners[b])
        guide=Group(guide_mesh,'吊衣桿定位線框');guide.hidden=p['hide_guide'];children.append(guide)
    if style_id not in ('louverdoor','emptycabinet','hangingrail','shelves','lightstrip','handle',*THRESHOLD_STYLES,*MOLDING_STYLES,*GRID_STYLES,*FRAME_STYLES,*DOOR058_STYLES):
        # Four actual edges only, at each style's original back plane.
        guide_mesh = Mesh()
        w,h = p['width']/100,p['height']/100
        back=template.get('thickness_cm',3)/100
        corners = [QVector3D(0,back,0),QVector3D(w,back,0),
                   QVector3D(w,back,h),QVector3D(0,back,h)]
        for i in range(4): guide_mesh.add_edge(corners[i],corners[(i+1)%4])
        children.append(Group(guide_mesh,GUIDE_NAME))
    group = Group(name=door_name(style_id))
    group.adopt(children)
    group.component = False
    group.ext = {KEY:{'version':VERSION,'params_cm':p,'style_id':style_id,'door_style':style_id if style_id in ('louverdoor','emptycabinet','hangingrail','shelves','lightstrip','handle','boxdoor','country',*THRESHOLD_STYLES,*MOLDING_STYLES,*GRID_STYLES,*FRAME_STYLES,*DOOR058_STYLES) else '058','panel_count':sum(row[3] for row in louver_layout(p)) if style_id=='louverdoor' else p['count'] if style_id=='shelves' else int(p['rows'])*2 if style_id in (*GRID_STYLES,'glassdoor') else 0 if style_id in ('emptycabinet','hangingrail','lightstrip','handle',*THRESHOLD_STYLES,*FRAME_STYLES,*MOLDING_STYLES) else 3 if style_id=='door058_three' else 2 if style_id=='door058_two' else 1 if style_id in DOOR058_STYLES else {'one':1,'two':2,'three':3,'country':1,'boxdoor':1}[style_id],'source_sha256':template['source_sha256']}}
    if style_id=='lightstrip':group.ext[KEY]['source_render_materials']=copy.deepcopy(template['source_render_materials'])
    if previous is not None:
        frame = group_frame(previous)
        group.xform = _rigid_frame(frame)
        for key in ('uid','name','layer','material','ifc','hidden','locked'):
            if hasattr(previous,key): setattr(group,key,copy.deepcopy(getattr(previous,key)))
        others = copy.deepcopy(getattr(previous,'ext',None) or {})
        others[KEY] = group.ext[KEY]; group.ext = others
        if previous.name in ('1肚自訂櫃門片','2肚自訂櫃門片','1\u5ea6自訂櫃門片','2\u5ea6自訂櫃門片','058櫃門片（一肚）','058櫃門片（兩肚）','058櫃門片（三肚）','058\u9580片（一肚）','058\u9580片（兩肚）','058\u9580片（三肚）','鄉村門片','玻璃格子','玻璃格子門用','玻璃格子櫃用','058門框（雙面造型）','058門框（前方造型、後方平面）','058框（雙面造型）','058框（前方造型、後方平面）','企口框（雙邊造型）','企口框（前方造型、後方平面）','058門（一肚）','058門（兩肚）','058門（三肚）','058門（玻璃格子門）','口框櫃門片','線板框（1216）','線板框（058）','門檻（門用）','門檻（淋浴間用）','一字取手','均分層板','燈條','素門框','吊衣桿','空櫃','百葉門片'):
            group.name=door_name(style_id)
    return group


from core.history import Command
from tools.base import Tool

class DoorChange(Command):
    """Replace only this door; preserve order and selection on undo/redo."""
    name = '櫃門片－樣式與元件選項'
    def __init__(self, scene, group, previous=None):
        self.group, self.previous = group, previous
        self.index = scene.groups.index(previous) if previous is not None else len(scene.groups)
        self.selection_before = set(scene.selection)
        self.materials_added={}
        if style_of(group) in ('lightstrip','hangingrail'):
            from core.materials import Material,register
            registry=dict(scene.materials)
            for recipe in ([hangingrail_material()] if style_of(group)=='hangingrail' else STYLES['lightstrip']['materials']):
                name=register(registry,Material.from_dict(recipe))
                if name not in scene.materials:
                    registry[name].finish=recipe['finish'];self.materials_added[name]=registry[name]
                for child in group.children:
                    if child.material and child.material.get('mat')==recipe['name'] and list(child.material.get('color',[]))==recipe['color'] and child.material.get('texture')==recipe.get('texture'):
                        child.material['mat']=name
                    for face in child.mesh.faces:
                        if face.attrs.get('mat')==recipe['name'] and list(face.attrs.get('color',[]))==recipe['color']:
                            face.attrs['mat']=name

    def do(self, scene):
        scene.materials.update(self.materials_added)
        if self.previous is not None and self.previous in scene.groups:
            scene.groups.remove(self.previous)
        if self.group not in scene.groups: scene.groups.insert(min(self.index,len(scene.groups)), self.group)
        scene.selection.clear(); scene.selection.add(self.group); scene.version += 1
    def undo(self, scene):
        for name,material in self.materials_added.items():
            if scene.materials.get(name) is material:scene.materials.pop(name)
        if self.group in scene.groups: scene.groups.remove(self.group)
        if self.previous is not None and self.previous not in scene.groups:
            scene.groups.insert(min(self.index,len(scene.groups)), self.previous)
        scene.selection.clear(); scene.selection.update(self.selection_before); scene.version += 1


def apply_door(viewport, params, previous=None, style_id=None):
    scene = viewport.scene
    if getattr(scene,'edit_group',None) is not None:
        raise ValueError('請先離開群組內部編輯，再選取整片門片。')
    if previous is not None and previous not in scene.groups:
        raise ValueError('選取的門片已不在目前模型中，請重新選取。')
    if previous is not None and getattr(previous,'locked',False):
        raise ValueError('此門片已鎖定，請先解除鎖定。')
    group = build_group(params,previous,style_id)
    if previous is None: group.layer = getattr(scene,'active_layer',None)
    viewport.history.execute(DoorChange(scene,group,previous))
    viewport.notify_scene_changed()
    return group


