class FourPointDoorScaleTool(_HostScaleTool):
    name='門片四點／門框六點拉伸'
    description='門片左右改寬、上下改高；門框可改深度；門檻左右改長度、前後改深度；造型截面固定。可輸入尺寸（公分）。'
    shortcut=None
    def __init__(self,app):
        super().__init__()
        self._door_app=app;self._frame_mode=False;self._threshold_mode=False;self._handle_mode=False;self._shelves_mode=False;self._lightstrip_mode=False;self._hangingrail_mode=False;self._emptycabinet_mode=False
        from PySide6.QtCore import QTimer
        self._middle_grip=None;self._middle_drag=None;self._louver_group=None
        self.dragging=False;self._pending_hover=None;self._last_preview_time=0.
        self._preview_timer=QTimer();self._preview_timer.setSingleShot(True)
        self._preview_timer.timeout.connect(self._flush_hover)
    def _valid_selection(self,viewport):
        selected=list(viewport.scene.selection)
        return (getattr(viewport.scene,'edit_group',None) is None and len(selected)==1
                and _is_door(selected[0]) and not getattr(selected[0],'locked',False))
    def _selection_bounds(self,viewport):
        if not self._valid_selection(viewport):return None,None
        return super()._selection_bounds(viewport)
    def _refresh_box(self,viewport):
        super()._refresh_box(viewport)
        if self._grip is not None:return
        if self._lo is None:
            self._middle_grip=None;self._louver_group=None;return
        from tools.scale import _Grip
        self._frame_mode=self._valid_selection(viewport) and style_of(next(iter(viewport.scene.selection))) in ('emptycabinet','shelves',*FRAME_STYLES)
        self._threshold_mode=self._valid_selection(viewport) and style_of(next(iter(viewport.scene.selection))) in THRESHOLD_STYLES
        self._handle_mode=self._valid_selection(viewport) and style_of(next(iter(viewport.scene.selection))) in LENGTH_ONLY_STYLES
        self._lightstrip_mode=self._valid_selection(viewport) and style_of(next(iter(viewport.scene.selection)))=='lightstrip'
        self._shelves_mode=self._valid_selection(viewport) and style_of(next(iter(viewport.scene.selection)))=='shelves'
        self._hangingrail_mode=self._valid_selection(viewport) and style_of(next(iter(viewport.scene.selection)))=='hangingrail'
        self._emptycabinet_mode=self._valid_selection(viewport) and style_of(next(iter(viewport.scene.selection)))=='emptycabinet'
        specs=[((0,.5,.5),(0,)),((1,.5,.5),(0,)),((.5,.5,0),(2,)),((.5,.5,1),(2,))]
        if self._handle_mode:specs=[((0,.5,.5),(0,)),((1,.5,.5),(0,))]
        if self._hangingrail_mode:
            p=effective_params(next(iter(viewport.scene.selection)))
            ty=14.37/(14.37+max(3.5,p['guide_back']));tz=3.5/(3.5+max(3.5,p['guide_top']))
            specs=[((0,ty,tz),(0,)),((1,ty,tz),(0,))]
        if self._threshold_mode:specs=[((0,.5,.5),(0,)),((1,.5,.5),(0,)),((.5,0,.5),(1,)),((.5,1,.5),(1,))]
        if self._frame_mode:specs += [((.5,0,.5),(1,)),((.5,1,.5),(1,))]
        group=next(iter(viewport.scene.selection))
        self._louver_group=group if style_of(group)=='louverdoor' else None
        middle=self._louver_group is not None and effective_params(group).get('show_mid',True)
        # Sentinel mask: this grip moves a rail, never scales the whole door.
        if middle:specs.append(((.5,.5,.5),()))
        if [(g.params,g.mask) for g in self._grips]!=specs:
            self._grips=[_Grip(params,mask) for params,mask in specs]
        self._middle_grip=self._grips[-1] if middle else None
        self.uniform=False;self.about_center=False
    def _grip_pos(self,grip):
        if grip is self._middle_grip and self._louver_group is not None:
            from PySide6.QtGui import QVector3D
            from core.group import group_frame
            g=self._louver_group;p=g.ext[KEY]['params_cm'];p=louver_params(p)
            z=p['rail']+(p['height']-2*p['rail'])*p['mid_position']/100
            return group_frame(g).map(QVector3D(p['width']/200,0,z/100))
        return super()._grip_pos(grip)
    def _flush_hover(self):
        import time
        self._preview_timer.stop();ctx=self._pending_hover;self._pending_hover=None
        if ctx is None or self._grip is None:return
        self._last_preview_time=time.monotonic()
        if self._middle_drag is not None:self._hover_middle(ctx)
        else:super().on_hover(ctx)
    def on_hover(self,ctx):
        if self._grip is None or self._louver_group is None:return super().on_hover(ctx)
        import time
        # Coalesce high-frequency mouse events; release always flushes the last
        # cursor position, so throttling cannot change the committed size.
        self._pending_hover=ctx
        wait=1/30-(time.monotonic()-self._last_preview_time)
        if wait<=0:self._flush_hover()
        elif not self._preview_timer.isActive():self._preview_timer.start(max(1,math.ceil(wait*1000)))
    def _hover_middle(self,ctx):
        from PySide6.QtGui import QVector3D
        state=self._middle_drag;vp=ctx.viewport
        point=self._snapped_point(ctx)
        if point is None:
            origin,direction=self._ray(vp,ctx.screen.x(),ctx.screen.y())
            if origin is None:return
            point=self._closest_on_line(origin,direction,state['point'],state['axis'])
        if point is None:return
        p=dict(state['params']);z=state['inverse'].map(point).z()*100
        pitch=STYLES['louverdoor']['pitch_cm']+1e-5
        z=max(p['rail']+p['mid']/2+pitch,min(p['height']-p['rail']-p['mid']/2-pitch,z))
        p['mid_position']=100*(z-p['rail'])/(p['height']-2*p['rail'])
        dx=ctx.screen.x()-self._grabbed_px[0];dy=ctx.screen.y()-self._grabbed_px[1]
        if dx*dx+dy*dy>16:self._moved=True
        if abs(p['mid_position']-state['current']['mid_position'])<1e-7:return
        original=copy.copy(state['group']);_restore_door(original,state['before'])
        fresh=build_group(p,original,'louverdoor')
        _restore_door(state['group'],_capture_door(fresh));state['current']=p
        vp.scene.version+=1;vp.update()
    def _finish_middle(self,viewport,commit=False):
        self._preview_timer.stop();self._pending_hover=None
        state=self._middle_drag
        if state is None:return
        _restore_door(state['group'],state['before']);viewport.scene.version+=1
        self._middle_drag=None;self._grip=None;self._anchor=None;self.dragging=False
        self._last=None;self._factors=(1.,1.,1.);self._box_version=-1
        if commit and state['current']!=state['params']:
            apply_door(viewport,state['current'],state['group'],'louverdoor')
        self._refresh_box(viewport);viewport.update()
    def on_release(self,viewport):
        self._flush_hover()
        if self._middle_drag is not None:
            if self._moved:self._finish_middle(viewport,True)
            return
        super().on_release(viewport)
    def on_cancel(self,viewport):
        self._preview_timer.stop();self._pending_hover=None
        if self._middle_drag is not None:return self._finish_middle(viewport)
        super().on_cancel(viewport)
    def on_deactivate(self,viewport):
        self._preview_timer.stop();self._pending_hover=None
        if self._middle_drag is not None:self._finish_middle(viewport)
        super().on_deactivate(viewport)
    def _anchor_for(self,grip):
        if self._hangingrail_mode:
            from tools.scale import _Grip
            return self._grip_pos(_Grip((1-grip.params[0],grip.params[1],grip.params[2]),grip.mask))
        return super()._anchor_for(grip)
    def on_activate(self,viewport):
        install_scale_hooks()
        super().on_activate(viewport)
        if self._middle_grip is not None:
            viewport.flash_status('百葉門片：四周綠點調寬高，中央紅點上下移動中橫槓；放開完成，Esc取消。',6000)
            return
        viewport.flash_status(('空櫃六點拉伸：改寬、高、深度；四周板厚及背板厚度固定。' if self._emptycabinet_mode else '吊衣桿兩點拉伸：只改長度，桿徑、端座及定位距離固定。' if self._hangingrail_mode else '燈條兩點拉伸：左右只改長度，截面、端蓋與材質保留。' if self._lightstrip_mode else '均分層板六點拉伸：改寬、高、深度；淨空自動均分，板厚與片數固定。' if self._shelves_mode else '一字取手兩點拉伸：左右只改長度，粗細與腳座固定。' if self._handle_mode else '門檻四點拉伸：左右改長度、前後改深度。' if self._threshold_mode else '門框六點拉伸：左右改寬、上下改高、前後改深度。' if self._frame_mode else '門片四點縮放：左右改寬、上下改高。')+'輸入數字為完整尺寸（cm）。',6000)
    def _grab(self,viewport,grip,screen_xy):
        if not self._valid_selection(viewport):return
        self._preview_timer.stop();self._pending_hover=None;self._last_preview_time=0.
        if grip is self._middle_grip:
            from core.group import group_frame
            from PySide6.QtGui import QVector3D
            group=next(iter(viewport.scene.selection));frame=group_frame(group);inverse,ok=frame.inverted()
            if not ok:return
            p=validate(group.ext[KEY]['params_cm'],'louverdoor')
            lengths=_basis(frame)[2]
            if any(abs(v-1)>1e-6 for v in lengths):p=effective_params(group)
            # World cursor maps to effective dimensions even for a native-scaled group.
            inverse=_rigid_frame(frame).inverted()[0]
            self._middle_drag={'group':group,'before':_capture_door(group),'params':p,'current':dict(p),
                               'point':self._grip_pos(grip),'axis':frame.mapVector(QVector3D(0,0,1)).normalized(),'inverse':inverse}
            self._grip=grip;self._grabbed_px=screen_xy;self._moved=False
            self._groups=[group];self._last=None;self.dragging=True
            viewport.flash_status('上下拖動紅色控制點可移動中橫槓；放開滑鼠完成，Esc取消。',5000)
            viewport.update();return
        masks=((0,),) if style_of(next(iter(viewport.scene.selection))) in LENGTH_ONLY_STYLES else ((0,),(1,)) if style_of(next(iter(viewport.scene.selection))) in THRESHOLD_STYLES else ((0,),(1,),(2,)) if style_of(next(iter(viewport.scene.selection))) in ('emptycabinet','shelves',*FRAME_STYLES) else ((0,),(2,))
        if grip.mask not in masks:return
        self.uniform=False;self.about_center=False
        super()._grab(viewport,grip,screen_xy)
    def on_click(self,ctx):
        vp=ctx.viewport
        if self._middle_drag is not None:
            self._pending_hover=ctx;self._flush_hover();self._finish_middle(vp,True);return
        if getattr(vp.scene,'edit_group',None) is not None:
            vp.flash_status('請先離開群組內部，再選取整片門片。',4000);return
        if self._grip is not None:return super().on_click(ctx)
        self._refresh_box(vp)
        if self._lo is not None and self._grip_under(vp,ctx.screen.x(),ctx.screen.y()) is not None:
            return super().on_click(ctx)
        target=vp.pick_group(ctx.screen.x(),ctx.screen.y())
        if target is not None and _is_door(target) and not getattr(target,'locked',False):
            vp.scene.select([target]);self._box_version=-1;self._refresh_box(vp);vp.update()
        elif not self._valid_selection(vp):
            vp.flash_status('請選取一片由本工具建立的門片。',4000)
    def on_key(self,viewport,key,modifiers):
        from PySide6.QtCore import Qt
        if key in (Qt.Key_Shift,Qt.Key_Control):return True
        return super().on_key(viewport,key,modifiers)
    def on_key_release(self,viewport,key):
        from PySide6.QtCore import Qt
        if key==Qt.Key_Control:return True
        return super().on_key_release(viewport,key)
    def _factors_for(self,ctx,viewport,sx,sy):
        fs=super()._factors_for(ctx,viewport,sx,sy)
        if fs is not None and (not all(math.isfinite(v) for v in fs) or min(fs)<=0):return None
        return fs
    def on_value(self,viewport,value):
        if self._middle_drag is not None:
            viewport.flash_status('中橫槓請上下拖動；精確位置可在元件選項輸入。',4000);return False
        # Host passes bare factors because value_is_unitless() is inherited.
        # For this dedicated tool, bare values are the target centimetres.
        if not (isinstance(value,tuple) and value and value[0]=='abs_len'):
            if not isinstance(value,(int,float)) or not math.isfinite(value) or value<=0:
                viewport.flash_status('請輸入大於零的完整尺寸（cm）。',4000);return False
            value=('abs_len',float(value)/100)
        if not isinstance(value[1],(int,float)) or not math.isfinite(value[1]) or value[1]<=0:return False
        if not self._valid_selection(viewport):return False
        group=next(iter(viewport.scene.selection))
        if self._grip is not None:mask=self._grip.mask
        elif self._last is not None:
            if getattr(self._last['cmd'],'group',None) is not group:
                self._last=None;return False
            mask=self._last['spec'][1]
        else:return False
        params=dict(group.ext[KEY]['params_cm'])
        params[{(0,):'width',(1,):'depth',(2,):'height'}[mask]]=value[1]*100
        try:validate(params,style_of(group))
        except ValueError as exc:
            viewport.flash_status(str(exc),4000);return False
        return super().on_value(viewport,value)
    def vcb_caption(self):
        grip=self._grip or self._hover_grip
        if grip is not None and grip is self._middle_grip:return '中橫槓上下位置'
        if self._emptycabinet_mode:return '空櫃尺寸（cm）' if grip is None else '深度（cm）' if grip.mask==(1,) else '寬（cm）' if grip.mask==(0,) else '高（cm）'
        if self._shelves_mode:return '層板範圍尺寸（cm）' if grip is None else '深度（cm）' if grip.mask==(1,) else '寬（cm）' if grip.mask==(0,) else '高（cm）'
        if self._hangingrail_mode:return '吊衣桿長度（cm）'
        if self._lightstrip_mode:return '燈條長度（cm）'
        if self._handle_mode:return '取手長度（cm）'
        if self._threshold_mode:return '門檻尺寸（cm）' if grip is None else '深度（cm）' if grip.mask==(1,) else '長度（cm）'
        if grip is None:return '門片尺寸（cm）'
        return '門框深度（cm）' if grip.mask==(1,) else '寬（cm）' if grip.mask==(0,) else '高（cm）'
    def drag_plane(self,viewport):
        if self._grip is None:return None
        cam=getattr(viewport,'camera',None)
        if cam is None:return None
        point=self._grip_pos(self._grip);normal=cam.eye()-point
        if normal.length()<1e-8:return None
        return point,normal.normalized()
    def value_label(self):
        if self._middle_drag is not None:
            return (f"{self._middle_drag['current']['mid_position']:.2f}%",self._grip_pos(self._middle_grip))
        return super().value_label()
    def scale_box_state(self):
        if self._lo is None:return None
        from PySide6.QtGui import QVector3D
        from core.history import scale_matrix
        lo,hi=self._lo,self._hi
        transform=(scale_matrix(self._anchor,self._factors,self._axes)
                   if self._grip is not None and self._middle_drag is None else None)
        def point(tx,tz,ty=.5):
            q=self._to_world(QVector3D(lo.x()+(hi.x()-lo.x())*tx,
                    lo.y()+(hi.y()-lo.y())*ty,lo.z()+(hi.z()-lo.z())*tz))
            return transform.map(q) if transform is not None else q
        corners=([point(0,.5,0),point(1,.5,0),point(1,.5,1),point(0,.5,1)] if self._threshold_mode
                 else [point(0,0),point(1,0),point(1,1),point(0,1)])
        grips=[]
        for grip in self._grips:
            if grip is self._middle_grip:
                grips.append((self._grip_pos(grip),'active' if grip is self._grip else 'hover' if grip is self._hover_grip else 'middle'))
                continue
            q=point(grip.params[0],grip.params[2],grip.params[1]);role='idle'
            if grip is self._grip:role='active'
            elif self._grip is not None and self._anchor is not None and (q-self._anchor).length()<1e-5:role='anchor'
            elif grip is self._hover_grip:role='hover'
            grips.append((q,role))
        # All anchors are existing opposite midpoints; never add extra grip dots.
        segments=[(corners[i],corners[(i+1)%4]) for i in range(4)]
        if self._handle_mode:segments=[(grips[0][0],grips[1][0])]
        if self._frame_mode:segments.append((point(.5,.5,0),point(.5,.5,1)))
        return {'segments':segments,'grips':grips}


def four_point_icon(window):
    from PySide6.QtCore import Qt,QRectF,QPointF
    from PySide6.QtGui import QIcon,QPixmap,QPainter,QPen,QPalette,QColor
    icon=QIcon();ink=window.palette().color(QPalette.ColorRole.ButtonText)
    for size in (32,64,128):
        pix=QPixmap(size,size);pix.fill(Qt.GlobalColor.transparent)
        p=QPainter(pix);p.setRenderHint(QPainter.RenderHint.Antialiasing);p.scale(size/32,size/32)
        p.setBrush(Qt.BrushStyle.NoBrush);p.setPen(QPen(ink,1.5));p.drawRect(QRectF(9,8,14,16))
        p.setPen(QPen(QColor('#37a58c'),1.8))
        for x,y,dx,dy in [(2,16,1,0),(30,16,-1,0),(16,1,0,1),(16,31,0,-1)]:
            tip=QPointF(x,y);base=QPointF(x+dx*6,y+dy*6)
            p.drawLine(tip,base)
            p.drawLine(tip,QPointF(x+dx*3-dy*2.5,y+dy*3+dx*2.5))
            p.drawLine(tip,QPointF(x+dx*3+dy*2.5,y+dy*3-dx*2.5))
        p.end();icon.addPixmap(pix)
    return icon
